<script setup lang="ts">
import { ref,onMounted,watch,computed } from 'vue';import { useRoute,useRouter,onBeforeRouteLeave,onBeforeRouteUpdate } from 'vue-router';import { api,statusName,duration,displayTime,catalog,loadCatalog } from '../lib/api';import {confirmAction} from '../lib/dialog';import type { Detail } from '../../shared/models';
const route=useRoute(),router=useRouter(),notice=ref(''),nextId=ref(''),d=ref<Detail|null>(null),error=ref(''),reason=ref(''),internal=ref(''),busy=ref(false);const back=computed(()=>typeof route.query.return==='string'&&/^\/admin\/submissions(?:\?|$)/.test(route.query.return)?route.query.return:'/admin/submissions');async function load(){d.value=await api<Detail>('/api/submissions/'+route.params.id+(route.query.revision?'?revision='+route.query.revision:''));const list=await api<{items:{id:string}[]}>('/api/admin/submissions?'+new URLSearchParams({event:d.value.submission.event_id,status:'pending',page:'1'}));nextId.value=list.items.find(x=>x.id!==d.value!.submission.id)?.id??'';}
watch(()=>[route.params.id,route.query.revision],()=>{reason.value='';internal.value='';notice.value='';void load().catch(e=>error.value=e.message);});
onMounted(async()=>{try{await loadCatalog();await load();}catch(e){error.value=(e as Error).message;}});
async function decide(action:string){if(!d.value||busy.value)return;if(action!=='approved'&&!reason.value.trim()){error.value='请填写对外原因';return;}if(!await confirmAction(`${action==='approved'?'通过':action==='rejected'?'驳回':'退回修改'}《${d.value.revision.title}》？\n${reason.value?'发送给投稿者的说明：'+reason.value:'将向投稿者发送审核结果通知。'}`))return;busy.value=true;error.value='';try{await api('/api/admin/submissions/'+d.value.submission.id+(action==='reopen'?'/reopen':'/reviews'),{operation_id:crypto.randomUUID(),expectedVersion:d.value.submission.version,expectedRevision:d.value.revision.id,...(action==='reopen'?{}:{decision:action}),reason:reason.value,internal_note:internal.value});await load();reason.value='';internal.value='';notice.value=(action==='approved'?'已通过':action==='rejected'?'已驳回':'已退回修改')+'，通知已进入发送队列。';}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function retry(id:string){try{await api('/api/admin/notifications/'+id+'/retry',{});await load();}catch(e){error.value=(e as Error).message;}}
async function leave(){return !busy.value&&(!(reason.value||internal.value)||await confirmAction('审核说明尚未提交，确定离开并放弃这些说明？'));}onBeforeRouteLeave(leave);onBeforeRouteUpdate(leave);
</script>
<template><div class="page"><RouterLink class="back" :to="back">← 返回投稿清单</RouterLink><p v-if="error" class="alert error" role="alert">{{ error }}</p><p v-if="notice" role="status" class="alert success">{{ notice }}</p><RouterLink v-if="nextId" class="button" :to="{path:'/admin/submissions/'+nextId,query:{return:back}}">下一份待审核 →</RouterLink><template v-if="d"><header class="page-head"><div><p class="eyebrow">{{ d.submission.public_number }} / REVISION {{ d.revision.revision_no }}</p><h1>{{ d.revision.title }}</h1><p class="muted">{{ d.form.type==='其他'?d.form.type_other:d.revision.type }} · {{ duration(d.revision.duration_seconds) }}</p></div><span class="badge" :class="d.submission.status">{{ statusName(d.submission.status) }}</span></header><div class="review-layout"><div><section class="paper"><h2>作品资料</h2><RouterLink v-if="d.revision.id!==d.revisions[0]?.id" :to="{query:{...route.query,revision:undefined}}">返回当前版本</RouterLink><p>{{ catalog.config?.categories.find(c=>c.id===d!.form.category_id)?.name }}{{ d.form.category_other?'：'+d.form.category_other:'' }}</p><p class="prewrap">{{ d.revision.description }}</p><a v-if="d.uploaded_file" class="button primary" :href="'/api/uploads/'+d.uploaded_file.id+'/download'">下载作品 · {{ d.uploaded_file.filename }}</a><a v-if="d.revision.delivery_url" class="button" :href="d.revision.delivery_url" target="_blank" rel="noopener noreferrer">打开作品预览 ↗</a><p v-if="d.revision.access_notes" class="hint prewrap">访问说明：{{ d.revision.access_notes }}</p><p class="prewrap">{{ d.revision.notes }}</p></section><section class="paper"><h2>负责人和制作人员</h2><p v-for="warning in d.warnings" class="alert warning" role="status">{{ warning }}</p><p class="hint">制作人员 {{ d.form.contributors.length }} 人 · {{ d.staff_limit_verified&&d.staff_limit?'已核实联投上限 '+d.staff_limit+' 人':'联投人数上限尚未核实' }}</p><p>负责人：{{ d.form.contact.name }} · UID {{ d.form.contact.uid }}<br>主投稿：{{ d.form.uploader.name }} · UID {{ d.form.uploader.uid }}<br>反馈邮箱：{{ d.revision.feedback_email }}</p><ol><li v-for="(p,i) in d.form.contributors" :key="i">{{ p.name }} <span class="mono">{{ p.uid }}</span> · {{ d.role_labels?.[p.role_option_id??'']??catalog.config?.roles.find(r=>r.id===p.role_option_id)?.label??'待核对职务' }}<small>{{ p.role_other }} {{ p.work_detail }}</small></li></ol></section><section class="paper"><h2>历史记录</h2><div v-for="r in d.reviews" :key="r.id" class="history-row"><strong>{{ r.action==='reopen'?'退回修改':statusName(r.action) }}</strong><small>{{ displayTime(r.created_at) }}</small><p>{{ r.reason }}</p><p v-if="r.internal_note" class="hint">内部备注：{{ r.internal_note }}</p></div><details><summary>提交版本（{{ d.revisions.length }}）</summary><p v-for="r in d.revisions" :key="r.id">修订 {{ r.revision_no }} · <RouterLink :to="{query:{...route.query,revision:r.id}}">{{ r.title }}</RouterLink> · {{ r.submitted_at?displayTime(r.submitted_at):'修改中草稿' }}</p></details></section></div><aside><section class="paper"><h2>审核决定</h2><template v-if="d.revision.id===d.revisions[0]?.id&&(d.submission.status==='pending'||d.submission.status==='approved')"><FieldLabel>发给投稿者的原因<textarea v-model="reason" rows="4" placeholder="驳回或退回修改时必填，请具体说明修改方向。"></textarea></FieldLabel><FieldLabel>管理员内部备注<textarea v-model="internal" rows="2" placeholder="不会发送给投稿者"></textarea></FieldLabel><div v-if="d.submission.status==='pending'" class="inline"><button class="primary" :disabled="busy" @click="decide('approved')">通过</button><button class="danger" :disabled="busy" @click="decide('rejected')">驳回</button></div><button v-else :disabled="busy" @click="decide('reopen')">退回修改</button><p class="hint">退回已编排节目前，需要先从节目单移除。</p></template><p v-else class="muted">等待投稿者修改并重新提交。</p></section><section class="paper"><h2>通知状态</h2><div v-for="n in d.notifications" :key="n.id" class="history-row"><span>{{ {queued:'等待发送',sending:'正在发送',sent:'供应商已接受',failed:'发送失败',delivered:'已送达',bounced:'退信'}[n.status]??n.status }}</span><small>{{ n.attempts }} 次尝试</small><p v-if="n.last_error" class="hint">{{ n.last_error }}</p><button v-if="n.status==='failed'" @click="retry(n.id)">重试通知</button></div><p class="hint">发信失败不会撤销审核结果。</p></section></aside></div></template></div></template>
